"""Build PROHOR's four evidence dossiers. pip install reportlab; install DejaVu fonts.
All content is deliberately editable below. Run from any directory.
"""
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether, Image
from reportlab.lib.units import mm
import zipfile

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public/docs'; OUT.mkdir(exist_ok=True,parents=True)
pdfmetrics.registerFont(TTFont('DV','/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'))
pdfmetrics.registerFont(TTFont('DVB','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'))
pdfmetrics.registerFontFamily('DV',normal='DV',bold='DVB')
C={'ink':colors.HexColor('#142d23'),'green':colors.HexColor('#176147'),'soft':colors.HexColor('#edf6ef'),'muted':colors.HexColor('#52665b'),'line':colors.HexColor('#d8e6dc'),'gray':colors.HexColor('#f6f9f7')}
ST={
 'eyebrow':ParagraphStyle('eyebrow',fontName='DVB',fontSize=8.2,leading=12,textColor=C['green'],spaceAfter=8),
 'title':ParagraphStyle('title',fontName='DVB',fontSize=23,leading=29,textColor=C['ink'],spaceAfter=10),
 'deck':ParagraphStyle('deck',fontName='DV',fontSize=11,leading=17,textColor=C['muted'],spaceAfter=17),
 'heading':ParagraphStyle('heading',fontName='DVB',fontSize=13,leading=18,textColor=C['ink'],spaceBefore=8,spaceAfter=7),
 'body':ParagraphStyle('body',fontName='DV',fontSize=9.4,leading=15,textColor=C['ink'],spaceAfter=10),
 'small':ParagraphStyle('small',fontName='DV',fontSize=8.4,leading=13,textColor=C['muted'],spaceAfter=8),
 'cell':ParagraphStyle('cell',fontName='DV',fontSize=8.2,leading=12.2,textColor=C['ink']),
 'cellhead':ParagraphStyle('cellhead',fontName='DVB',fontSize=8.2,leading=12,textColor=C['ink']),
 'callout':ParagraphStyle('callout',fontName='DV',fontSize=9.4,leading=15,textColor=C['ink'])
}
W,H=A4
REPO='https://github.com/tufayelahmedsuhagcc-dotcom/prohor'
NASA='https://osdr.nasa.gov/bio/repo/data/studies/OSD-575'
NOAA='https://www.swpc.noaa.gov/products/planetary-k-index'
def P(s,style='body'):return Paragraph(s,ST[style])
def link(label,url):return f'<link href="{escape(url, {chr(34):"&quot;"})}" color="#176147"><u>{escape(label)}</u></link>'
def h(s):return P(s,'heading')
def para(s):return P(s)
def small(s):return P(s,'small')
def tab(rows,widths):
 t=Table([[P(x,'cellhead' if i==0 else 'cell') for x in row] for i,row in enumerate(rows)],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),C['soft']),('LINEBELOW',(0,0),(-1,0),.5,C['line']),('LINEBELOW',(0,1),(-1,-1),.35,C['line']),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
 return t
def box(s):
 t=Table([[P(s,'callout')]],colWidths=[499]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),C['soft']),('BOX',(0,0),(-1,-1),.5,C['line']),('LEFTPADDING',(0,0),(-1,-1),13),('RIGHTPADDING',(0,0),(-1,-1),13),('TOPPADDING',(0,0),(-1,-1),11),('BOTTOMPADDING',(0,0),(-1,-1),11)]));return t
def refs(items):return [h('Sources & further reading')]+[small('• '+link(a,b)) for a,b in items]
def start(no,title,desc):return [P(f'JUDGES’ LIBRARY  /  DOSSIER {no}','eyebrow'),P(title,'title'),P(desc,'deck')]
def newpage(kicker,title):return [PageBreak(),P(kicker.upper(),'eyebrow'),P(title,'title')]
def build(name,no,story):
 path=OUT/name
 def page(c,doc):
  c.setFillColor(C['green']);c.setFont('DVB',9);c.drawString(48,H-32,'PROHOR')
  c.setFillColor(C['muted']);c.setFont('DV',7.6);c.drawRightString(W-48,H-32,f'JUDGES’ LIBRARY   /   {no}')
  c.setStrokeColor(C['line']);c.line(48,H-42,W-48,H-42)
  c.setFont('DV',7);c.drawString(48,29,'Independent research prototype  •  Not a medical device')
  c.drawRightString(W-48,29,f'{doc.page:02d}')
 doc=SimpleDocTemplate(str(path),pagesize=A4,leftMargin=48,rightMargin=48,topMargin=59,bottomMargin=52,title='PROHOR Judges Library — '+no,author='Skorpe Monad',pageCompression=1)
 doc.build(story,onFirstPage=page,onLaterPages=page);print('Created',path)

s=start('01','The mission & the demo.','A concise story for the room: what PROHOR addresses, what a judge can try, and where the evidence begins.')
s += [box('<b>The idea in one sentence.</b> PROHOR helps a crew member turn separate health readings into an explainable, personal comparison and a human-review handover — even when a previously cached app is offline.'),Spacer(1,14),h('The operational gap'),para('A long-duration crew needs to track health while dealing with limited resources and potential communication delays. Numbers alone can be hard to interpret: a change has meaning only when the person, measurement method, prior observations and missing data are visible.'),para('PROHOR is a research prototype, not a medical service. It brings the observation, baseline explanation, research context and handover into one interface. It does not diagnose illness, set flight rules or replace a clinician.'),h('What makes the experience inspectable'),tab([['Moment','What the interface shows','Why it matters'],['Observe','A reading, its unit and a labeled data mode.','Separates synthetic demonstration from personal input.'],['Compare','A prior-day median, band and coverage.','A reviewer can inspect the rule instead of trusting a score.'],['Review','Research context and a structured handover.','Keeps the next decision with a human.']],[82,205,212]),Spacer(1,12),small('Designed for the 2026 NASA Space Apps health-monitoring challenge. Independent team project; no NASA endorsement is implied.')]
s += newpage('02 / guided walkthrough','A demo judges can reproduce.')
s += [para('The following steps use the built-in <b>synthetic</b> CDR-01 scenario. Nothing in this walkthrough is a real astronaut’s personal health record.'),tab([['Step','Action','What to point out'],['1  Start','Open Mission overview and select “See the change” in the guided tour.','The tour selects demo crew CDR-01 on flight day 146 and opens Trends.'],['2  Explain','Inspect sleep in Trends &amp; baselines.','5.6 h is simulated; the 7.4 h personal median is from the synthetic enrollment window. The flagged state is a prototype rule, not a medical finding.'],['3  Investigate','Use “Explore the evidence” from the overview tour.','The NASA explorer is a separate historical Inspiration4 study. Open its source and choose analyte and subject.'],['4  Hand over','Use “Prepare for review” to open Crew handover.','Inspect a local export and the explicit statement that nothing was transmitted. A human decides what comes next.'],['5  Explore','Open Data &amp; settings for local CSV tools.','A fresh local profile must build its own baseline; importing data is not the same as proving device integration.']],[65,205,229]),Spacer(1,14),box('<b>Offline check:</b> Visit online first, wait for the service worker and cached assets, then turn off the network and reload. Cache eviction, browser restrictions or a failed first visit can prevent offline operation.'),Spacer(1,12),para('A well-framed presentation starts with the problem, demonstrates one interaction all the way through, then closes with limitations. The evidence dossiers provide deeper technical detail when a judge asks.'), Image(str(ROOT/'docs/screenshots/judges-synthetic-trend.png'),width=440,height=202), Spacer(1,5), small('Actual PROHOR Trends view. CDR-01 and all readings shown are synthetic.') ]
s += newpage('03 / positioning','The promise, honestly bounded.')
s += [h('Who benefits and how'),para('The intended users are crew members and their reviewers in a future mission-health workflow. Today, the prototype demonstrates a useful interaction pattern for transparent self-observation. It has not been evaluated with an operational crew or shown to improve medical outcomes.'),h('What a judge can verify'),tab([['Question','Where to look'],['Does the demo use real or invented readings?','Demo is explicitly synthetic; user entries are local; NASA research is separately labeled.'],['Can I verify the scientific source?','NASA evidence links the OSD-575 archive and verifies the bundled submitted CSV against its manifest.'],['Why was a change flagged?','Trends exposes the baseline window, median, day coverage, directional rule and change band.'],['Does this replace an expert?','No. Routine prompts and handover support human review; symptoms and approved procedures take precedence.']],[230,269]),Spacer(1,12),h('Team'),para('Skorpe Monad: Tufayel Ahmed (Team Lead · Main Developer &amp; Designer), Annapurna Das Protyasha (Researcher · Concept Maker), Rakthim Deb Rudro (Advisor), Mir Shahi Ahmod (Data Scientist), and Tonusri Deb Diggi (Video &amp; Photo Editor).'),*refs([('Live prototype','https://prohor-rho.vercel.app/'),('Official challenge','https://www.spaceappschallenge.org/2026/challenges/health-monitoring-software/'),('Repository and reproducible source',REPO)])]
build('PROHOR_01_Mission_and_Demo.pdf','01',s)

s=start('02','Data & scientific evidence.','Source by source: what is measured, what is calculated, and where interpretation must stop.')
s += [box('<b>Four separate data contexts.</b> Personal readings and synthetic records enter the baseline workflow. NASA archive values support a separate research explorer. NOAA Kp supplies Earth geomagnetic context only.'),Spacer(1,15),h('The source inventory'),tab([['Source','Used in PROHOR','Do not infer'],['NASA OSD-575','Submitted Inspiration4 metabolic-panel CSV; research charts and descriptive comparisons.','Live crew telemetry, Mars evidence, or validation of personal alerts.'],['NASA OSD-569 / OSD-571','Study titles, descriptions and source links.','Additional personal readings or analysis of their laboratory values.'],['NASA OSD-87','Optional mouse-study metadata, outside the default human filter.','Human clinical thresholds or a user’s condition.'],['NOAA planetary Kp','Earth geomagnetic observation context, with timestamps.','A Mars/cabin reading, individual dose, or cause of a health change.'],['Local / demo data','User-entered or imported readings; deterministic synthetic demo records.','A live sensor or a NASA clinical dataset.']],[115,196,188]),Spacer(1,12),para('NASA Human Research Program references provide framing about spaceflight hazards and measurement context. They are not endorsements or validation of PROHOR’s numerical rule.'),small('The snapshot and data views label source and freshness. A network fetch time is not the same as the time an observation was measured.')]
s += newpage('02 / traceable computation','Follow the OSD-575 evidence.')
s += [h('Source, identity and preservation'),para('The explorer reads the original submitted comprehensive metabolic panel for four coded Inspiration4 participants on a three-day 2021 mission. The preserved file contains <b>531 rows, 19 analytes and seven categorical collection points</b>: L−92, L−44, L−3, R+1, R+45, R+82 and R+194. L indicates days before launch; R is days after return.'),para('<b>File:</b> LSDS-8_Comprehensive_Metabolic_Panel_CMP.upload_SUBMITTED.csv<br/><b>Size:</b> 25,275 bytes<br/><b>SHA-256:</b> dab247eb794edab59aaaa683c85fd1f2dbf4ae3684872739338e10ead4192a0c'),para('The browser parses the source rows and checks the bytes against the bundled manifest where Web Crypto is available. A mismatch blocks archive analysis; lack of a supported checksum is disclosed. A matching hash demonstrates identity relative to the manifest, not scientific correctness or protection against replacement of both file and manifest.'),h('One reproducible result: glucose, mg/dL'),tab([['Subject','Pre-flight median','R+1 value','R+1 change','R+45 value'],['C001','80','90','+10','84'],['C002','72','83','+11','44'],['C003','75','103','+28','36'],['C004','83','97','+14','43']],[80,110,95,110,104]),Spacer(1,10),para('Each pre-flight median is calculated from the subject’s finite pre-flight observations; the R+1 change subtracts that median. The plotted sample positions are categorical, not evenly spaced days. Non-numeric or censored values are retained as source text and excluded from arithmetic; missing values are not filled.'),small('At R+45, C002, C003 and C004 fall below the recorded laboratory interval (65–99 mg/dL). This is a source-context review cue, not a diagnosis or proof of a flight effect; fasting status and measurement circumstances are not established here.')]
s += newpage('03 / interpretation','What the numbers cannot tell us.')
s += [h('Limits before interpretation'),para('Four people and a short mission cannot establish population reference ranges or validate long-duration monitoring. The pre/post pattern cannot isolate mission exposure from other influences. Source laboratory reference intervals are metadata, not PROHOR’s personal change bands. Legacy race-labeled eGFR fields are preserved in the raw file but excluded from selectable analyses.'),h('NASA metadata and NOAA Kp'),para('The app’s read-only adapter attempts NASA OSDR study metadata and NOAA SWPC planetary Kp through same-origin endpoints. Validated responses may be served from an in-process cache or a bundled fallback when the upstream is unavailable. An observation’s timestamp and the retrieval timestamp describe different things. The studies library is curated, not a search across all NASA research.'),box('<b>Data integrity is not clinical validation.</b> Source citation, byte verification and reproducible calculations help a judge check the work. They do not establish clinical sensitivity, specificity, safety or usefulness.'),Spacer(1,12),h('How to reproduce the archive'),para('Download the submitted CSV from the NASA source below, compare the SHA-256, inspect the study metadata and source rows, and run the repository’s research tests. The repository’s <b>DATA-PROVENANCE.md</b> describes source files, normalization and constraints in detail.'),*refs([('NASA OSD-575 study',NASA),('Original NASA CSV','https://osdr.nasa.gov/geode-py/ws/studies/OSD-575/download?source=datamanager&file=LSDS-8_Comprehensive_Metabolic_Panel_CMP.upload_SUBMITTED.csv'),('OSD-569','https://osdr.nasa.gov/bio/repo/data/studies/OSD-569'),('OSD-571','https://osdr.nasa.gov/bio/repo/data/studies/OSD-571'),('NOAA SWPC planetary Kp',NOAA),('Full data provenance',REPO+'/blob/main/docs/DATA-PROVENANCE.md')])]
build('PROHOR_02_Data_and_Evidence.pdf','02',s)

s=start('03','Technology & methodology.','An inspectable path from input to interpretation: rules, integration boundaries and reproducibility.')
s += [h('A deliberately simple architecture'),tab([['Layer','Current implementation'],['Input','Local user entry or CSV validation; deterministic synthetic fixture in a separate demo workspace.'],['State','Client-side workspace and localStorage; no personal health submission or cloud sync endpoint.'],['Computation','Pure TypeScript functions normalize supported units, select prior days and apply PROHOR-IQR-3.0.'],['Presentation','React views show trends, data coverage, schematic atlas, NASA evidence and handover.'],['Public feeds','Same-origin read-only adapter for NASA OSDR metadata and NOAA Kp, with validation and fallback snapshots.'],['Offline','Vite build and service worker precache the app, public data and PDF library after a successful initial visit.']],[113,386]),Spacer(1,14),box('<b>Trust boundary:</b> public-source requests do not include personal readings. Local records are not submitted by the app to the public feeds. Browser extensions, hosting logs and exported files have separate privacy considerations.'),Spacer(1,15),h('Why keep the algorithm deterministic?'),para('Given the same inputs and rule version, the same comparison can be reproduced without an internet connection or runtime AI service. The user can see the values and assumptions behind a result. Determinism improves inspectability; it does not establish medical validity.')]
s += newpage('02 / baseline rule','The comparison, step by step.')
s += [h('Personal observations'),para('For a local signal on day d, use days d−30 through d−1 inclusive; never include the current or future day. Select the latest timestamped reading for each prior day, with the last input row breaking exact ties. If that selected reading is invalid, it is excluded rather than replaced by an older same-day value. Missing and non-finite values are excluded; there is no zero filling.'),para('A minimum of seven distinct usable prior days is required. Seven to 20 days are labeled provisional; 21 to 30 established. These are interface design choices, not statistical confidence or clinical certification.'),box('<b>Rule PROHOR-IQR-3.0</b><br/>median = Q(0.50)   ·   IQR = Q(0.75) − Q(0.25)<br/>width = max(1.5 × IQR, signal-specific noise floor)<br/>band = median ± width'),Spacer(1,14),para('Quantiles use linear interpolation at (n−1)q after sorting the values. A value strictly outside the applicable side of the band is marked for review. Equality is not flagged. The chart’s shaded area is the middle 50% (IQR), not the wider change band; the exact band is in the explanation panel.'),h('Worked synthetic example'),para('For CDR-01 on flight day 146, the demo displays 5.6 hours of sleep against a 7.4-hour synthetic median. Sleep has a one-hour noise floor and the rule checks lower values. The example demonstrates interface behavior, not evidence that a crew member has a sleep disorder. The 30-day demo enrollment period is frozen at FD 111–140 for scenario days 142–147.'),small('A stable but unhealthy baseline can still lead to a within-baseline state. Missing data are not a reassuring result; sudden or severe symptoms require approved procedures regardless of app state.')]
s += newpage('03 / deployment and verification','From source to a working build.')
s += [h('Public integration contract'),para('The two allowlisted endpoints are <b>GET /api/feeds?feed=studies</b> and <b>GET /api/feeds?feed=space-weather</b>. The server checks upstream responses, applies a timeout and validates shapes. A request can return fresh network data, a prior server cache, or a bundled dated snapshot. The client also validates responses; a malformed successful response is not silently accepted.'),h('Input quality and safety controls'),para('Supported ranges and ordinal checks reject unsupported input; they are software checks rather than medical safety ranges. CSV imports validate as a batch, so invalid rows do not partially change the workspace. Local and demo modes do not share baseline records. A corrupted local workspace is protected from silent overwrite. Exported files are under user control and are not encrypted.'),h('How to reproduce'),tab([['Command','Purpose'],['npm ci','Install locked dependencies.'],['npm run typecheck','Check TypeScript project.'],['npm test','Run automated unit tests for engine, storage, feed and research behavior.'],['npm run build','Generate production assets and service-worker precache in web/.'],['npm start','Serve the built app and the same-origin public-feed adapter.']],[155,344]),Spacer(1,10),para('The repository includes browser checks for workflows, offline reload, mobile layouts, source-integrity behavior and selected accessibility rules. Passing software checks does not establish device safety, accessibility certification or clinical performance.'),*refs([('Source repository',REPO),('Full methodology',REPO+'/blob/main/docs/METHODOLOGY.md'),('Architecture and security',REPO+'/blob/main/docs/ARCHITECTURE.md'),('Test report',REPO+'/blob/main/docs/TEST-REPORT.md')])]
build('PROHOR_03_Technology_and_Method.pdf','03',s)

s=start('04','Safety, impact & next steps.','A credible pathway from a promising interface to a rigorously evaluated future system.')
s += [box('<b>Core principle:</b> a review flag is a prompt to examine context, not a diagnosis; no flag is not a safety clearance. Severe or sudden symptoms and approved mission procedures take precedence.'),Spacer(1,13),h('What exists today'),para('A research prototype with a synthetic story, optional local input, deterministic personal comparisons, a schematic body-system navigator, separately labeled NASA research, NOAA context and a human-readable handover. It is built to make assumptions visible and to work after caching, rather than to make a clinical decision on the user’s behalf.'),h('What does not exist'),tab([['Not implemented / not established','Why the distinction matters'],['Clinical validation or flight qualification','No sensitivity, specificity, outcome benefit, regulatory approval or NASA endorsement is claimed.'],['Live medical devices or astronaut telemetry','The demonstration uses generated readings; local entries are user-supplied.'],['Encrypted records, accounts or remote sync','Local browser storage and exports are not a secure clinical record system.'],['Automatic treatment or causal inference','Co-occurring changes do not prove a common cause; routine prompts are not prescriptions.']],[235,264]),Spacer(1,13),small('The atlas is a schematic navigation aid. It does not scan an organ or establish its condition. NOAA Kp does not measure individual space-radiation exposure.')]
s += newpage('02 / risk controls','Safety and privacy by design.')
s += [h('Controls currently implemented'),para('<b>Explainability:</b> source, units, personal window, coverage and a visible rule can be inspected. <b>Data quality:</b> invalid and missing measurements do not become normal values; invalid CSV import is atomic. <b>Separation:</b> synthetic, local and historical-research records remain distinct. <b>Provenance:</b> OSD-575 source bytes are checked against a manifest where supported.'),h('Privacy realities'),para('Readings, notes, preferences and action states are stored in browser localStorage. The application has no health-record submission endpoint. Browser storage can be read by same-origin scripts, compromised by extensions or access to the device, denied or erased. Exports are ordinary unencrypted files. External sites and hosting providers have their own data practices.'),para('Use non-identifying data for demonstrations. Production use would require an accountable operator, access controls, encryption, incident response, retention and recovery procedures, and an appropriate legal and regulatory review.'),h('Questions a judge may ask'),tab([['Question','Grounded answer'],['Is this a medical device?','No. It is a non-diagnostic prototype and has not undergone a medical or regulatory assessment.'],['Does NASA data validate the alert?','No. OSD-575 is historical research displayed separately; it does not determine personal thresholds.'],['Can it run offline?','After an initial successful cache, the app and bundled resources can work without network access; storage restrictions and eviction remain possible.'],['Where does a handover go?','An export is created for the user; it is not automatically transmitted to a clinician.']],[198,301])]
s += newpage('03 / future work','Impact requires evidence.')
s += [h('A practical evaluation roadmap'),tab([['Phase','Work required','Evidence of progress'],['1  Understand','Consult crew, flight surgeons and human-factors experts; identify tasks and hazards.','Documented user needs, task analysis and hazard register.'],['2  Protect','Threat-model the workflow; design access, encryption, audit and recovery.','Independent security review and tested recovery procedures.'],['3  Measure','Validate sensors, input quality and data provenance; specify acceptable use.','Measurement protocols and device-integration testing.'],['4  Evaluate','Prospectively assess usability, safety and algorithm behavior in appropriate populations.','Predefined outcomes, documented false alarms/missed changes and independent clinical review.'],['5  Govern','Assess regulation, ownership, monitoring and operational accountability.','Explicit go/no-go decisions before any clinical or flight use.']],[80,201,218]),Spacer(1,14),para('These are proposed next steps, not completed integrations or established outcomes. Potential Earth applications, such as supporting longitudinal self-observation in remote settings, would also require separate validation in those contexts.'),h('Transparent development'),para('AI-assisted tools were used in website updates, documentation and presentation production. The team must review the complete submission and disclose all AI tools and uses that actually apply. A polished presentation is not a substitute for scientific or operational review.'),*refs([('NASA Human Research Program hazards','https://www.nasa.gov/hrp/hazards/'),('NASA standard measures','https://www.nasa.gov/reference/standard-measures/'),('Project security and limitations',REPO+'/blob/main/docs/SECURITY.md'),('Methodology and scientific boundaries',REPO+'/blob/main/docs/METHODOLOGY.md'),('Official participant FAQs','https://www.spaceappschallenge.org/resources/participant-faqs/')])]
build('PROHOR_04_Safety_Impact_and_Roadmap.pdf','04',s)
files=sorted(OUT.glob('PROHOR_0*.pdf'))
with zipfile.ZipFile(OUT/'PROHOR_Judges_Library.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in files:z.write(f,f.name)
print('Library ZIP:',len(files),'documents')
